ALTER TABLE cars DROP CONSTRAINT ck_cars_category;
ALTER TABLE cars ADD CONSTRAINT ck_cars_category CHECK (category IS NULL OR CASE category WHEN 'GR_1' THEN 1 WHEN 'GR_2' THEN 1 WHEN 'GR_3' THEN 1 WHEN 'GR_4' THEN 1 WHEN 'GR_B' THEN 1 WHEN 'GR_N' THEN 1 WHEN 'GR_X' THEN 1 ELSE 0 END = 1);
ALTER TABLE cars DROP CONSTRAINT ck_cars_drivetrain;
ALTER TABLE cars ADD CONSTRAINT ck_cars_drivetrain CHECK (drivetrain IS NULL OR CASE drivetrain WHEN 'FR' THEN 1 WHEN 'MR' THEN 1 WHEN 'RR' THEN 1 WHEN 'FF' THEN 1 WHEN 'FOUR_WD' THEN 1 ELSE 0 END = 1);
